const $=s=>document.querySelector(s),sleep=ms=>new Promise(r=>setTimeout(r,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
async function until(fn,label){const end=performance.now()+30000;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(15);}}
const click=s=>{assert($(s),'Missing '+s);$(s).click();},field=(s,v)=>{$(s).value=String(v);$(s).dispatchEvent(new Event('change',{bubbles:true}));};
const input={id:'conditions-input',name:'Synthetic conditional input',state:'connected',type:'input',onmidimessage:null};
Object.defineProperty(navigator,'requestMIDIAccess',{configurable:true,value:async()=>({inputs:new Map([[input.id,input]]),onstatechange:null})});
const packet=(channel,note,value=127)=>input.onmidimessage?.({data:new Uint8Array([0x90+channel-1,note,value]),timeStamp:performance.now()});
async function tap(channel,note){packet(channel,note);await sleep(35);packet(channel,note,0);await sleep(25);}
const profileId='1f33a04a1c5b924a0b2b1ea12a35216ddebed8d099cd6ed7cb6e5890e03d5ec3';
let app;
async function importCatalog(url){const text=await(await fetch(url)).text(),dt=new DataTransfer();dt.items.add(new File([text],url.split('/').pop(),{type:'application/json'}));$('#catalog-file').files=dt.files;$('#catalog-file').dispatchEvent(new Event('change',{bubbles:true}));await until(()=>$('#catalog-status').textContent.startsWith('Imported '),'Catalog import');assert($('#catalog-status').textContent.includes('0 file(s) rejected'),$('#catalog-status').textContent);field('#catalog-profile',profileId);}
async function apply(){field('#catalog-profile',profileId);field('#catalog-device',input.id);click('#catalog-apply');await until(()=>$('#catalog-profile')?.options.length===2,'Mapping redraw');}
async function run(){
 const {state,engine}=app,d=state.decks[0],track=d.track;
 const report={startedAt:new Date().toISOString(),scope:'Actual browser app and recovered factory catalogs; synthetic MIDI, authored audio/prepared stems; no hardware, musical separation, native or full reference acceptance',checks:[],errors:[],fullParity:false,physicalCompatibilityVerified:false,phase:sessionStorage.getItem('conditions-phase')||'upgrade'};$('#conditions-run').disabled=true;
 try{
  await engine.resume();engine.audioMonitor.mutePhysical(true);assert(engine.audioMonitor.snapshot().physicalMuted,'Physical mute');await until(()=>!state.analysis,'Analysis idle');
  click('[data-panel="midi"]');await until(()=>!$('#catalog-status').textContent.startsWith('Reading'),'Catalog ready');
  if(report.phase==='upgrade'){
   assert(state.mappings.length===0,'Use a fresh isolated origin');
   await importCatalog('/api/controller-fixtures/factory-001.json');assert($('#catalog-profile-detail').textContent.includes('56 translated assignments'),'v1 fixture');
   click('#midi-connect');await until(()=>$('#catalog-device').options.length===2&&$('#catalog-profile').options.length===2,'Input/catalog ready');await apply();await until(()=>state.mappings.length===56,'v1 binding');
   const prior=JSON.stringify(state.mappings);await importCatalog('/api/controller-fixtures/factory-002.json');assert($('#catalog-profile-detail').textContent.includes('335 translated assignments'),'Newest authenticated profile did not replace v1 in catalog view');assert($('#catalog-profile-detail').textContent.includes('Official Serato'),'v2 source label');assert(JSON.stringify(state.mappings)===prior,'Upgrade replaced existing assignments');
   await apply();await until(()=>state.mappings.length===335,'v2 added cases');assert(JSON.stringify(state.mappings.slice(0,56))===prior,'v1 applied assignments changed');
   report.checks.push('Actual v1→v2 import upgraded catalog by reviewed revision, retained 56 applied assignments and added 279 new assignments');sessionStorage.setItem('conditions-phase','restored');sessionStorage.setItem('conditions-upgrade',JSON.stringify(report));report.awaitingReload=true;
  }else{
   await until(()=>$('#catalog-profile').options.length===2,'Restored catalog');field('#catalog-profile',profileId);assert($('#catalog-profile-detail').textContent.includes('335 translated assignments'),'Reload did not select newest trusted revision');assert(state.mappings.length===335,'Reload lost conditional assignments');
   click('#midi-connect');await until(()=>input.onmidimessage,'Input connected');click('#modal-close');
   Object.assign(track,{duration:12,bpm:120,grid:0,gridWarpMarkers:[],gridMarkers:[],analyzed:true,cues:Array(8).fill(null),savedLoops:Array(8).fill(null)});Object.assign(d,{position:0,rate:1,keylock:false,keyShift:0,loop:false,reverse:false,quantize:false,slip:false,stemSlip:'off',sync:false,mode:'INT',stems:[true,true,true,true],stemFX:[false,false,false,false]});
   const sr=engine.ctx.sampleRate,original=engine.ctx.createBuffer(2,sr*12,sr),stems=Array.from({length:4},()=>engine.ctx.createBuffer(2,sr*12,sr));
   for(let c=0;c<2;c++)for(let n=0;n<original.length;n++){const v=.1*Math.sin(2*Math.PI*(c?550:330)*n/sr);original.getChannelData(c)[n]=v;stems[0].getChannelData(c)[n]=v;}
   engine.buffers.set(track.id,original);engine.stemBuffers.set(track.id,stems);engine.clearDeckScratchCache(0);engine.mix(0,'level',.8);state.settings['Show Beat Jump Controls']=false;state.settings['Lock Playing Deck']=false;
   const mode=async(note,name)=>{$('#conditions-status').textContent='Testing '+name+'…';await tap(2,note);await until(()=>d.controllerPadMode===name,'Mode '+name);};
   await engine.recordStart();
   state.selected=track.id;state.prepare=[];await tap(1,3);await until(()=>state.prepare.includes(track.id),'Prepare normal');
   const other=state.tracks.find(t=>t.id!==track.id);state.selected=other.id;packet(2,4);await sleep(20);await tap(1,3);await until(()=>state.panel==='prepare','Shift Prepare');assert(!state.prepare.includes(other.id),'Both modifier cases executed');packet(2,4,0);await sleep(20);await tap(1,3);await until(()=>state.prepare.includes(other.id),'Modifier released');
   report.checks.push('Actual factory modifier press/release selected mutually exclusive Prepare add/open cases and released back to normal');
   await mode(15,'hot cues');d.position=.5;await tap(7,0);await until(()=>!!track.cues[0],'Hot cue creation');packet(7,0);await until(()=>d.playing,'Hot cue audition');await sleep(120);packet(7,0,0);await until(()=>!d.playing,'Hot cue release');await tap(7,8);await until(()=>!track.cues[0],'Shift hot cue delete');report.checks.push('Hot Cues created/auditioned a real cue, released playback, and Shift deleted it');
   await mode(16,'auto loop');d.position=1;await tap(7,16);await until(()=>d.loop,'Auto Loop');await tap(7,16);await until(()=>!d.loop,'Auto Loop exit');report.checks.push('Auto Loop source pad toggled the actual loop');
   packet(2,7);await until(()=>d.playing,'Playback for Roll');packet(2,7,0);await mode(20,'loop roll');packet(7,80);await until(()=>d.loop,'Momentary Roll');await mode(15,'hot cues');packet(7,80,0);await until(()=>!d.loop,'Roll release after mode change');assert(d.playing,'Roll release stopped original playback');await tap(2,7);await until(()=>!d.playing,'Pause after Roll');report.checks.push('Roll used actual transport and released its captured owner after changing mode to Hot Cues');
   await mode(21,'manual loop');d.loop=false;d.position=2;await tap(7,96);await until(()=>d.loopIn===2,'Manual In');d.position=3;await tap(7,97);await until(()=>d.loop&&d.loopOut===3,'Manual Out');await tap(7,102);await until(()=>!!track.savedLoops[d.loopSlot||0],'Manual Save');await tap(7,98);await until(()=>!d.loop,'Manual toggle');report.checks.push('Manual Loop inputs set real In/Out, saved a loop and toggled it');
   await mode(17,'stems');packet(2,7);await until(()=>d.playing,'Playback for Stems');packet(2,7,0);await tap(7,32);await until(()=>d.stems[0]===false,'Stem mute');assert(engine.voices.get(0)?.stemGains?.length===5,'Prepared five-source voice missing');await tap(7,32);await until(()=>d.stems[0]===true,'Stem restore');await tap(2,7);await until(()=>!d.playing,'Pause after Stems');report.checks.push('Stems source mode routed mute/restore into an actual prepared five-source playback voice; separation quality/activation continuity not tested');
   state.samples[0][0].track=track.id;state.samples[0][0].mode='Hold';await mode(18,'sampler');packet(7,48);await until(()=>state.samples[0][0].playing,'Sampler start');packet(7,48,0);await until(()=>!state.samples[0][0].playing,'Sampler release');report.checks.push('Sampler source mode started/stopped the actual Hold sampler slot');
   d.position=1;await mode(19,'pitch play');await tap(7,73);await until(()=>d.pitchCue===1&&track.cues[1],'Pitch cue selection');packet(7,64);await until(()=>d.playing&&!d.processing,'Pitch Play start');assert(d.keylock,'Pitch Play did not enable keylock');await sleep(120);packet(7,64,0);await until(()=>!d.playing,'Pitch Play release');report.checks.push('Pitch Play Shift selected/created a cue; actual pad played with keylock and released');
   state.scratch[0][0].track=other.id;state.scratch[0][0].start='Start';await mode(22,'scratch bank');await tap(7,112);await until(()=>d.track.id===other.id,'Scratch Bank load');await tap(7,120);await until(()=>d.track.id===track.id,'Scratch Bank previous');report.checks.push('Scratch Bank loaded an actual track and Shift restored the previous deck track');
   const blob=await engine.recordStop(),audio=await engine.ctx.decodeAudioData(await blob.arrayBuffer());report.audio={frames:audio.length,sampleRate:audio.sampleRate,channels:audio.numberOfChannels,rms:[]};for(let c=0;c<audio.numberOfChannels;c++){let sum=0;for(const v of audio.getChannelData(c)){assert(Number.isFinite(v),'Nonfinite recorded audio');sum+=v*v;}report.audio.rms.push(Math.sqrt(sum/audio.length));}assert(report.audio.channels===2&&report.audio.rms.every(v=>v>.001),'Missing actual stereo output');
   report.priorUpgrade=JSON.parse(sessionStorage.getItem('conditions-upgrade'));report.completed=true;
  }
 }catch(error){report.errors.push({message:error.message,stack:error.stack});}
 finally{for(const d of state.decks)engine.pause(d);if(engine.recording)await engine.recordStop();report.finishedAt=new Date().toISOString();$('#conditions-results').textContent=JSON.stringify(report,null,2);$('#conditions-status').textContent=report.errors.length?'Failed: '+report.errors.map(e=>e.message).join('; '):report.awaitingReload?'Upgrade retained. Reload, then run performance workflow.':'Scoped eight-mode workflow passed; playback stopped';}
}
$('#conditions-run').onclick=run;
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[1].track,'Actual app');app=window.openPlay;$('#conditions-run').disabled=false;$('#conditions-run').textContent=sessionStorage.getItem('conditions-phase')?'Run restored performance workflow':'Run factory catalog upgrade';}
boot().catch(error=>$('#conditions-status').textContent=error.message);
